 [1] "county"   "state"    "acres92"  "acres87"  "acres82"  "farms92" 
 [7] "farms87"  "farms82"  "largef92" "largef87" "largef82" "smallf92"
[13] "smallf87" "smallf82" "region"  
```


:::

```{.r .cell-code}
# find number of cols and rows
ncol(agpop) 
```

::: {.cell-output .cell-output-stdout}

```
[1] 15
```


:::

```{.r .cell-code}
nrow(agpop) 
```

::: {.cell-output .cell-output-stdout}

```
[1] 3078
```


:::

```{.r .cell-code}
# find mean and sd of acres92
mean(agpop$acres92, na.rm = TRUE)
```

::: {.cell-output .cell-output-stdout}

```
[1] 308582.4
```


:::

```{.r .cell-code}
sd(agpop$acres92, na.rm = TRUE)
```

::: {.cell-output .cell-output-stdout}

```
[1] 425312.8
```


:::

```{.r .cell-code}
## Modern summary table using gtsummary
# install.packages("gtsummary") # Run this once in your console if you don't have it
library("gtsummary")
agpop |> 
  select(region, acres92, acres87, largef92, farms92) |> 
  tbl_summary(
    by = region, 
    statistic = list(all_continuous() ~ "{mean} ({sd})")
  )
```

